#!/usr/bin/env node
/**
 * 黄果短剧：把适配层内联进入口层，生成单个自包含 widget 文件。
 *
 *   lib/huangguo.js + lib/entries/huangguo-{home,resource}.js
 *     → widgets/huangguo{,-resource}.js
 *
 * 生成物顶部带 "Do not edit directly" 标记；要改逻辑请改 lib/，再跑 npm run build:huangguo。
 */
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const CORE = path.join(ROOT, "lib", "huangguo.js");
const BANNER = "/* Generated by scripts/build-huangguo.js from lib/huangguo.js. Do not edit directly. */";

const TARGETS = [
  { entry: "lib/entries/huangguo-home.js", output: "widgets/huangguo.js" },
  { entry: "lib/entries/huangguo-resource.js", output: "widgets/huangguo-resource.js" },
];

function read(rel) {
  return fs.readFileSync(path.join(ROOT, rel), "utf8").replace(/\r\n/g, "\n");
}

const core = fs.readFileSync(CORE, "utf8").replace(/\r\n/g, "\n");
if (!/function hgGcmEncrypt\(/.test(core) || !/function hgPlayback\(/.test(core)) {
  console.error("lib/huangguo.js 缺少关键实现，构建中止");
  process.exit(1);
}

for (const target of TARGETS) {
  const entry = read(target.entry);
  if (!/WidgetMetadata\s*=/.test(entry)) {
    console.error(`${target.entry} 缺少 WidgetMetadata 赋值`);
    process.exit(1);
  }
  const output = `${BANNER}\n\n${core.trimEnd()}\n\n${entry.trimEnd()}\n`;
  fs.writeFileSync(path.join(ROOT, target.output), output);
  const lines = output.split("\n").length;
  console.log(`✓ ${target.output}  ${(output.length / 1024).toFixed(1)}KB / ${lines} 行`);
}
